<script>
    // Target DateTime for countdown
    const targetDateStr = '<?= $isOpen ? $closeDateTime : $openDateTime ?>';
    let targetDate = targetDateStr ? new Date(targetDateStr.replace(/-/g, '/')).getTime() : null;

    function updateCountdown() {
        if (!targetDate || isNaN(targetDate)) return;

        const now = new Date().getTime();
        const difference = targetDate - now;

        if (difference <= 0) {
            document.getElementById('cdDays').innerText = '00';
            document.getElementById('cdHours').innerText = '00';
            document.getElementById('cdMinutes').innerText = '00';
            document.getElementById('cdSeconds').innerText = '00';
            return;
        }

        const days = Math.floor(difference / (1000 * 60 * 60 * 24));
        const hours = Math.floor((difference % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
        const minutes = Math.floor((difference % (1000 * 60 * 60)) / (1000 * 60));
        const seconds = Math.floor((difference % (1000 * 60)) / 1000);

        document.getElementById('cdDays').innerText = String(days).padStart(2, '0');
        document.getElementById('cdHours').innerText = String(hours).padStart(2, '0');
        document.getElementById('cdMinutes').innerText = String(minutes).padStart(2, '0');
        document.getElementById('cdSeconds').innerText = String(seconds).padStart(2, '0');
    }

    if (targetDate) {
        updateCountdown();
        setInterval(updateCountdown, 1000);
    }

    // Closed System Alert
    function alertClosedSystem() {
        Swal.fire({
            icon: 'info',
            title: 'ระบบยังไม่เปิดรับสมัคร',
            text: 'กรุณาติดตามกำหนดการและประกาศวันรับสมัครอย่างเป็นทางการจากทางโรงเรียน',
            confirmButtonText: 'รับทราบ',
            confirmButtonColor: '#ff758c'
        });
    }

    // PDPA Modal Handler for Registration
    let selectedLevel = 1;
    const registerPdpaModal = new bootstrap.Modal(document.getElementById('registerPdpaModal'));
    const acceptPdpaCheckbox = document.getElementById('acceptPdpaCheckbox');
    const btnProceedRegister = document.getElementById('btnProceedRegister');

    function openRegisterPDPA(level) {
        selectedLevel = level;
        document.getElementById('pdpaModalTitle').innerHTML = "<i class='bx bx-shield-quarter me-2'></i> ข้อตกลงการสมัครระดับชั้น ม." + level;
        acceptPdpaCheckbox.checked = false;
        btnProceedRegister.disabled = true;
        registerPdpaModal.show();
    }

    acceptPdpaCheckbox.addEventListener('change', function () {
        btnProceedRegister.disabled = !this.checked;
    });

    btnProceedRegister.addEventListener('click', function () {
        window.location.href = '<?= site_url('new-admission/pre-check/') ?>' + selectedLevel;
    });

    // Auto show Announcement Modal on page load
    document.addEventListener('DOMContentLoaded', function () {
        const homeAnnounceModalEl = document.getElementById('homeAnnouncementModal');
        if (homeAnnounceModalEl) {
            const homeAnnounceModal = new bootstrap.Modal(homeAnnounceModalEl);
            homeAnnounceModal.show();
        }
    });
</script>
